package com.secureauth.core;

import java.io.*;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.security.spec.KeySpec;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.PBEKeySpec;
import java.util.regex.Pattern;

public class AuthenticationService {

    private static final Pattern SAFE_USERNAME = Pattern.compile("^[a-zA-Z0-9._@-]{1,64}$");
    private static final Map<String, Integer> failedAttempts = new ConcurrentHashMap<>();
    private static final int MAX_ATTEMPTS = 5;
    private final AuditLogger auditLogger;
    private final CredentialStore credentialStore;

    public AuthenticationService(AuditLogger auditLogger, CredentialStore credentialStore) {
        this.auditLogger = auditLogger;
        this.credentialStore = credentialStore;
    }

    public AuthResult authenticate(String username, String password, Map<String, String> context) {
        if (username == null || password == null) {
            return AuthResult.failure("Invalid credentials");
        }

        if (!SAFE_USERNAME.matcher(username).matches()) {
            auditLogger.logEvent("AUTH_REJECTED", sanitizeForLog(username), context);
            return AuthResult.failure("Invalid username format");
        }

        if (isLockedOut(username)) {
            auditLogger.logEvent("AUTH_LOCKED", username, context);
            return AuthResult.failure("Account locked");
        }

        String storedHash = credentialStore.getPasswordHash(username);
        if (storedHash == null) {
            auditLogger.logEvent("AUTH_UNKNOWN_USER", username, context);
            return AuthResult.failure("Invalid credentials");
        }

        if (verifyPassword(password, storedHash)) {
            failedAttempts.remove(username);
            auditLogger.logEvent("AUTH_SUCCESS", username, context);
            return AuthResult.success(username);
        } else {
            recordFailure(username);
            auditLogger.logEvent("AUTH_FAILURE", username, context);
            return AuthResult.failure("Invalid credentials");
        }
    }

    private boolean isLockedOut(String username) {
        return failedAttempts.getOrDefault(username, 0) >= MAX_ATTEMPTS;
    }

    private void recordFailure(String username) {
        failedAttempts.merge(username, 1, Integer::sum);
    }

    private static final int PBKDF2_ITERATIONS = 210_000;
    private static final int PBKDF2_KEY_LENGTH = 256;
    private static final int SALT_LENGTH = 16;
    private static final SecureRandom SECURE_RANDOM = new SecureRandom();

    private boolean verifyPassword(String password, String storedHash) {
        // storedHash format: base64(salt)$base64(derivedKey)
        try {
            int sep = storedHash.indexOf('$');
            if (sep < 0) {
                return false;
            }
            byte[] salt = Base64.getDecoder().decode(storedHash.substring(0, sep));
            byte[] expected = Base64.getDecoder().decode(storedHash.substring(sep + 1));
            byte[] computed = deriveKey(password, salt);
            return MessageDigest.isEqual(computed, expected);
        } catch (Exception e) {
            return false;
        }
    }

    /**
     * Hashes a password with a freshly generated random salt using PBKDF2.
     * Returns a string in the form base64(salt)$base64(derivedKey) suitable for storage.
     */
    private String hashPassword(String password) {
        try {
            byte[] salt = new byte[SALT_LENGTH];
            SECURE_RANDOM.nextBytes(salt);
            byte[] hash = deriveKey(password, salt);
            return Base64.getEncoder().encodeToString(salt) + "$"
                    + Base64.getEncoder().encodeToString(hash);
        } catch (Exception e) {
            throw new RuntimeException("Hash failure", e);
        }
    }

    private byte[] deriveKey(String password, byte[] salt) throws Exception {
        KeySpec spec = new PBEKeySpec(password.toCharArray(), salt, PBKDF2_ITERATIONS, PBKDF2_KEY_LENGTH);
        SecretKeyFactory factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");
        return factory.generateSecret(spec).getEncoded();
    }

    private String sanitizeForLog(String input) {
        return input.replaceAll("[^a-zA-Z0-9._@\\-]", "_");
    }
}

class AuditLogger {

    private final String logDirectory;
    private final NotificationService notificationService;

    public AuditLogger(String logDirectory, NotificationService notificationService) {
        this.logDirectory = logDirectory;
        this.notificationService = notificationService;
    }

    public void logEvent(String eventType, String subject, Map<String, String> context) {
        String timestamp = Instant.now().toString();
        String logEntry = String.format("%s|%s|%s|%s%n",
                timestamp, eventType, subject, formatContext(context));

        try {
            Path logFile = Paths.get(logDirectory, "auth-audit.log");
            Files.write(logFile, logEntry.getBytes(), 
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND);
        } catch (IOException e) {
            System.err.println("Failed to write audit log: " + e.getMessage());
        }

        if ("AUTH_LOCKED".equals(eventType)) {
            notificationService.alertSecurityTeam(eventType, subject, context);
        }
    }

    private String formatContext(Map<String, String> context) {
        if (context == null) return "";
        StringBuilder sb = new StringBuilder();
        for (Map.Entry<String, String> entry : context.entrySet()) {
            sb.append(entry.getKey()).append("=").append(entry.getValue()).append(";");
        }
        return sb.toString();
    }
}

class NotificationService {

    private final String alertScript;

    public NotificationService(String alertScript) {
        this.alertScript = alertScript;
    }

    public void alertSecurityTeam(String eventType, String subject, Map<String, String> context) {
        String sourceIp = context != null ? context.getOrDefault("source_ip", "unknown") : "unknown";
        String alertMessage = buildAlertMessage(eventType, subject, sourceIp);
        executeAlert(alertMessage);
    }

    private String buildAlertMessage(String eventType, String subject, String sourceIp) {
        return String.format("Security Alert: %s for user %s from %s", eventType, subject, sourceIp);
    }

    private void executeAlert(String message) {
        try {
            ProcessBuilder pb = new ProcessBuilder(alertScript);
            pb.environment().put("ALERT_MESSAGE", message);
            pb.start();
        } catch (IOException e) {
            System.err.println("Alert execution failed: " + e.getMessage());
        }
    }
}

class CredentialStore {
    private final Map<String, String> credentials = new HashMap<>();

    public void addUser(String username, String passwordHash) {
        credentials.put(username, passwordHash);
    }

    public String getPasswordHash(String username) {
        return credentials.get(username);
    }
}

class AuthResult {
    private final boolean success;
    private final String message;
    private final String username;

    private AuthResult(boolean success, String message, String username) {
        this.success = success;
        this.message = message;
        this.username = username;
    }

    public static AuthResult success(String username) {
        return new AuthResult(true, "Authenticated", username);
    }

    public static AuthResult failure(String message) {
        return new AuthResult(false, message, null);
    }

    public boolean isSuccess() { return success; }
    public String getMessage() { return message; }
    public String getUsername() { return username; }
}
